details.command:
kubectl patch pod app --type='merge' -p '
{
  "spec": {
    "containers": [
      {
        "name": "writer",
        "image": "busybox",
        "command": [
          "sh",
          "-c",
          "echo \"<h1>Hello, Kubernetes!</h1>\" > /srv/index.html && sleep 3600"
        ],
        "volumeMounts": [
          {
            "mountPath": "/srv",
            "name": "shared"
          }
        ]
      }
    ]
  }
}'
